use std::{env, process};
use test_programs::preview1::{assert_errno, open_scratch_directory};

const FILENAME: &str = "test.txt";
const EXPECTED: &[u8] = b"truncation test file\n";

unsafe fn read_file_contents(dir_fd: wasip1::Fd) -> Vec<u8> {
    let file_fd = wasip1::path_open(dir_fd, 0, FILENAME, 0, wasip1::RIGHTS_FD_READ, 0, 0)
        .expect("opening the file for reading");

    let mut buffer = [0u8; 128];
    let nread = wasip1::fd_read(
        file_fd,
        &[wasip1::Iovec {
            buf: buffer.as_mut_ptr(),
            buf_len: buffer.len(),
        }],
    )
    .expect("reading file content");

    wasip1::fd_close(file_fd).expect("closing the file");

    buffer[..nread].to_vec()
}

unsafe fn test_file_truncation_readonly(dir_fd: wasip1::Fd) {
    // The file should have its expected contents before any truncation attempt.
    assert_eq!(
        read_file_contents(dir_fd),
        EXPECTED,
        "file contents before the truncation attempt"
    );

    // Opening the file with the truncation flag must be rejected: the directory
    // was preopened with only read permission for files, so truncation (which
    // requires write access) is not permitted.
    assert_errno!(
        wasip1::path_open(
            dir_fd,
            0,
            FILENAME,
            wasip1::OFLAGS_TRUNC,
            wasip1::RIGHTS_FD_READ,
            0,
            0,
        )
        .expect_err("truncating a file without write permission should fail"),
        wasip1::ERRNO_PERM
    );

    // The file contents must remain unchanged after the failed truncation.
    assert_eq!(
        read_file_contents(dir_fd),
        EXPECTED,
        "file contents after the failed truncation attempt"
    );
}

fn main() {
    let mut args = env::args();
    let prog = args.next().unwrap();
    let arg = if let Some(arg) = args.next() {
        arg
    } else {
        eprintln!("usage: {prog} <scratch directory>");
        process::exit(1);
    };

    // Open scratch directory
    let dir_fd = match open_scratch_directory(&arg) {
        Ok(dir_fd) => dir_fd,
        Err(err) => {
            eprintln!("{err}");
            process::exit(1)
        }
    };

    // Run the tests.
    unsafe { test_file_truncation_readonly(dir_fd) }
}
